initialize = function(W, L, A, C, D, Y, outcome_type, tau, k = Inf) {
  assert_trt(A, tau)
  assert_character(W, null.ok = TRUE)
  assert_character(C, len = tau, null.ok = TRUE)
  assert_character(D, len = tau, null.ok = TRUE) # competing risk indicators
  assert_character(Y, min.len = ifelse(outcome_type == "survival", 2, 1))
  assert_list(L, types = c("NULL", "character"), len = tau, null.ok = TRUE)
  assert_number(k, lower = 0, upper = Inf)

  self$W <- W
  self$L <- L
  self$A <- A
  self$C <- C

  if (outcome_type == "survival") {
    self$Y <- last(Y)
    self$N <- Y[1:length(Y) - 1]
    self$D <- D
  } else {
    self$Y <- Y
  }

  self$k <- k
  self$tau <- tau
},

history = function(var = c("L", "A"), t) {
  private$l <- t - self$k - 1
  private$.var <- match.arg(var)
  if (private$.var == "A" && self$tau > 1 && length(self$A) == 1) {
    return(as.vector(na.omit(self$W)))
  }
  ans <- switch(private$.var,
    L = private$parents_L(t),
    A = private$parents_A(t)
  )
  private$.var <- NULL
  private$l <- NULL
  as.vector(na.omit(c(self$W, ans)))

check_lmtp_data = function(task) {
  for (time in seq_len(task$time_horizon)) {
    r <- task$is_at_risk(task$natural, time)
    o <- task$observed(task$natural, time - 1)
    i <- o %and% r

    A_t <- current_trt(task$vars$A, time)

    data_t <- task$natural[i, c(A_t, task$vars$W, unlist(task$vars$L[time])), drop = FALSE]

    if (any(is.na(data_t))) {
      return("Missing data found in treatment and/or covariate nodes for uncensored observations")
    }
  }

  TRUE
}

assert_lmtp_data <- checkmate::makeAssertionFunction(check_lmtp_data)

check_shifted_data <- function(natural, shifted, trt, cens) {
  is_same <- setdiff(names(natural), c(unlist(trt), cens))

  if (!(identical(natural[is_same], shifted[is_same]))) {
    return("The only columns that can be different between `data` and `shifted` are those indicated in `trt` and `cens`")
  }

  if (is.null(cens)) {
    return(TRUE)
  }

  if (!all(shifted[cens] == 1)) {
    return("Censoring variables should be 1 in 'shifted'")
  }

  TRUE
}

assert_correctly_shifted <- checkmate::makeAssertionFunction(check_shifted_data)

make_folds <- function(data, V = 10, strata_ids = NULL, cluster_ids = NULL) {
  n <- nrow(data)
  folds <- vector("list", V)

  if (V == 1) {
    folds[[1]] <- list(
      training_set = seq_len(n), 
      validation_set = seq_len(n)
    )
    return(folds)
  }

  if (is.null(cluster_ids)) {
    unit_to_rows <- as.list(seq_len(n))
    unit_strata <- if (is.null(strata_ids)) rep("1", n) else as.character(strata_ids)
  } else {
    cluster_chr <- as.character(cluster_ids)
    unique_clusters <- unique(cluster_chr)
    unit_to_rows <- lapply(unique_clusters, function(cl) which(cluster_chr == cl))

    if (is.null(strata_ids)) {
      unit_strata <- rep("1", length(unique_clusters))
    } else {
      strata_chr <- as.character(strata_ids)
      # A cluster spanning multiple strata is assigned to its modal stratum,
      # since clusters cannot be split across folds.
      unit_strata <- vapply(unique_clusters, function(cl) {
        s <- strata_chr[cluster_chr == cl]
        tab <- table(s)
        names(tab)[which.max(tab)]
      }, character(1))
    }
  }

  n_units <- length(unit_to_rows)
  if (V > n_units) {
    warning(sprintf("`k` (%d) exceeds the number of units (%d); defaulting to leave-one-out cross-validation", V, n_units))
    V <- n_units
    folds <- vector("list", V)
  }

  fold_of_unit <- integer(n_units)
  for (s in unique(unit_strata)) {
    idx <- which(unit_strata == s)
    shuffled <- sample(idx)
    fold_of_unit[shuffled] <- rep(seq_len(V), length.out = length(shuffled))
  }

  for (j in seq_len(V)) {
    val_units <- which(fold_of_unit == j)
    train_units <- which(fold_of_unit != j)
    folds[[j]] <- list(
      training_set = sort(unlist(unit_to_rows[train_units], use.names = FALSE)),
      validation_set = sort(unlist(unit_to_rows[val_units], use.names = FALSE))
    )
  }

  folds
}

run_ensemble <- function(data, y, learners, outcome_type, id, folds) {
  n_ids <- length(unique(data[[id]]))
  if (folds > n_ids) {
    cli::cli_abort(
      "The number of Super Learner folds ({folds}) exceeds the number of unique IDs ({n_ids}) in the training data. Set {.code .learners_trt_folds} or {.code .learners_outcome_folds} in {.fn lmtp_control} to at most {n_ids}."
    )
  }
  family <- ifelse(outcome_type == "binomial", binomial(), gaussian())
  cv_control <- SuperLearner::SuperLearner.CV.control(V = folds)
  features <- setdiff(names(data), c(id, y))
  X <- data[, features, drop = FALSE]
  Y <- data[[y]]
  fit <- SuperLearner::SuperLearner(
    Y, X, family = family[[1]], SL.library = learners,
    id = data[[id]], method = "method.NNLS",
    env = environment(SuperLearner::SuperLearner),
    cvControl = cv_control
  )

  class(fit) <- append("lmtp_ensemble", class(fit))
  fit

